package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes a create-owner telephone into E.164 form: a leading '+' and country code are kept
 * when present, otherwise country code '+61' is assumed and a single leading '0' is dropped from
 * the national digits. Spaces, dashes and brackets are stripped, and 8 to 15 digits are required
 * after the '+'. Mutates the validated {@link OwnerFieldsDto} in place (so {@link BuildOwner}
 * stores the E.164 value), or throws {@link InvalidTelephoneException} for a 400 when the value
 * cannot form a valid E.164 number.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String original = request.getTelephone();
        String e164 = toE164(original);
        if (e164 == null) {
            throw new InvalidTelephoneException(original);
        }
        request.setTelephone(e164);
    }

    /**
     * Converts a raw telephone into E.164 ('+' followed by 8 to 15 digits), or returns
     * {@code null} when it cannot form a valid E.164 number.
     */
    public static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        // Strip spaces, dashes and brackets.
        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            // Keep the explicit country code; the remainder must be all digits.
            digits = cleaned.substring(1);
        }
        else {
            // Assume '+61' and drop a single leading '0' from the national digits.
            String national = cleaned;
            if (national.startsWith("0")) {
                national = national.substring(1);
            }
            digits = "61" + national;
        }
        if (!digits.matches("\\d{8,15}")) {
            return null;
        }
        return "+" + digits;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;

/**
 * Rejects a create-owner request whose E.164 telephone is already used by any other owner,
 * throwing {@link DuplicateTelephoneException} for a 409. Runs after {@link NormalizeOwnerTelephone}
 * has converted the request telephone to E.164, and compares against every stored owner's telephone
 * converted to E.164 the same way.
 */
public class CheckOwnerTelephoneUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone.equals(NormalizeOwnerTelephone.toE164(existing.getTelephone()))) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}

